mo={senang:'<path d="M51 72q9 12 18 0z" fill="#8a3a4a"/><path d="M55 77q5-4 10 0q-5 4-10 0z" fill="#f08a9a"/><rect x="57.6" y="71.6" width="4.8" height="3.6" rx="1.2" fill="#fff"/>',tenang:'<path d="M52 72q4 5 8 0q4 5 8 0" stroke="#b86a6a" fill="none" stroke-width="1.8" stroke-linecap="round"/>',sedih:'<path d="M53 77q7-6 14 0" stroke="#b86a6a" fill="none" stroke-width="1.8" stroke-linecap="round"/>',cemas:'<path d="M52 76q2-3 4 0t4 0t4 0t4 0" stroke="#b86a6a" fill="none" stroke-width="1.8" stroke-linecap="round"/>',lelah:'<path d="M54 76.5h12" stroke="#b86a6a" stroke-width="1.8" stroke-linecap="round"/>'}[e],
ex={sedih:'<path class="tr" d="M43 68q-3.5 5.5 0 8.5q3.5-3 0-8.5z" fill="#9edcff"/>',cemas:'<path class="sw" d="M96 36q-4 8 0 10q4-2 0-10z" fill="#9edcff"/>',lelah:'<ellipse cx="45" cy="70" rx="9" ry="2.6" fill="#8a6aa8" opacity=".25"/><ellipse cx="75" cy="70" rx="9" ry="2.6" fill="#8a6aa8" opacity=".25"/><text class="zz" x="96" y="30" font-size="14" font-weight="800" fill="#7a6ad8">z</text>'}[e]||'',
