ear=(sg,r)=>`<g style="transform-box:view-box;transform-origin:${sg?'40px 40px':'78px 40px'};transform:rotate(${r}deg)"><g class="er"><path d="${sg?'M33 42C17 33 8 16 15 6C23 -1 40 14 49 36z':'M70 36C67 16 71 1 80 1C91 2 93 22 86 42z'}" fill="url(#f${n})" filter="url(#z${n})"/><path d="${sg?'M35 38C24 31 17 18 21 10C27 6 38 18 45 34z':'M75 35C73 19 76 8 81 8C87 9 88 24 83 38z'}" fill="url(#p${n})"/></g></g>`,
