const radar=b=>{const V=[b.ph/6,b.ga/6,1-b.who/25],L=['Depresi','Kecemasan','Stres'],P=(r,i)=>{const a=(-90+i*120)*Math.PI/180;return[+(110+r*70*Math.cos(a)).toFixed(1),+(100+r*70*Math.sin(a)).toFixed(1)]},pt=r=>[0,1,2].map(i=>P(r,i)).join(' '),Q=(v,i)=>P(Math.max(v,.06),i);
return `<svg viewBox="0 0 220 200" role="img" aria-label="Diagram radar: depresi ${b.ph} dari 6, kecemasan ${b.ga} dari 6, stres ${25-b.who} dari 25" style="width:100%;max-width:300px;display:block;margin:auto">${[.33,.67,1].map(r=>`<polygon points="${pt(r)}" fill="none" stroke="var(--line)" stroke-width="1.5"/>`).join('')}${[0,1,2].map(i=>`<line x1="110" y1="100" x2="${P(1,i)[0]}" y2="${P(1,i)[1]}" stroke="var(--line)"/>`).join('')}<polygon points="${V.map((v,i)=>Q(v,i)).join(' ')}" fill="var(--pr)" fill-opacity=".28" stroke="var(--pr)" stroke-width="2.5"/>${V.map((v,i)=>`<circle cx="${Q(v,i)[0]}" cy="${Q(v,i)[1]}" r="4.5" fill="var(--pr)"/>`).join('')}${L.map((l,i)=>{const[x,y]=P(1.15,i);return `<text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" font-weight="800" fill="var(--tx)">${l}</text>`}).join('')}</svg>`};
const recap=b=>`<div class="c"><div class="top"><h3>Rekap hasil</h3><span class="pl p${b.lvl}">Tingkat awal: ${CAT[b.lvl]}</span></div><p class="mut sm" style="margin:0 0 6px">${dstr(b.at)}</p>${radar(b)}${[['Depresi (PHQ-2)',b.ph,6,lv3(b.ph,[3,5])],['Kecemasan (GAD-2)',b.ga,6,lv3(b.ga,[3,5])],['Stres dan energi (WHO-5)',25-b.who,25,b.who<7?2:b.wt?1:0]].map(([l,v,m,k])=>`<div class="row"><div class="t"><span>${l}</span><span><b>${v}/${m}</b> <span class="pl p${k}">${CAT[k]}</span></span></div><div class="mt"><i style="width:${v/m*100}%"></i></div></div>`).join('')}${met('Kesepian (UCLA-3)',b.ucl,9)}<p class="mut sm"><b>Skrining awal, bukan diagnosis.</b> Hasil ini membantu Mimo menyesuaikan diri denganmu.</p></div>`;
const Result=()=>{const b=U().baseline;R(Pg(`<div class="mm idle" style="width:min(55vw,230px)">${mimo(LK(),EMO())}</div><p style="font-weight:700;margin:0">${['Mimo senang melihat kondisimu.','Mimo akan menemanimu pelan-pelan.','Kamu tidak harus menghadapinya sendiri.'][b.lvl]}</p>`,`<h1>Rekap hasilmu</h1>${recap(b)}<div class="c" id="sg">${sag()}</div><button class="b" data-a="home">Masuk ke beranda dan main sama Mimo</button>`),Result)};
const Hist=()=>{const u=U(),c=u.checkins.slice(-14),F=['','😣','😔','😐','🙂','😄'];Shell('hist',`<h1>Riwayat</h1><div class="hm" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))">${recap(u.baseline)}<div class="c"><h3>Check-in suasana hatimu</h3>${c.length?`<div class="bars">${c.map(k=>`<div title="${dstr(k.t)}"><i style="height:${k.mood*20}%"></i></div>`).join('')}<u style="bottom:${bm()*20}%"></u></div><p class="mut sm">Batang = suasana hati 1–5. Garis putus-putus = patokan awalmu dari WHO-5.</p>${c.slice().reverse().map(k=>`<div class="row sm"><div class="t"><span>${dstr(k.t)} ${F[k.mood]||''}</span><span class="mut">tidur ${['','<5 jam','5–6 jam','7–8 jam','>8 jam'][k.sleep]||'-'}</span></div></div>`).join('')}`:'<p class="mut">Belum ada check-in. Ngobrol dengan Mimo di beranda untuk memulai.</p>'}</div></div>`,Hist)};

if(U())enter();else Auth();
